export const X_AXIS: Readonly<Vec3> = Object.freeze({ x: 1, y: 0, z: 0 });
/** The world +Y axis (up). */
export const Y_AXIS: Readonly<Vec3> = Object.freeze({ x: 0, y: 1, z: 0 });
